import csv
import io
import re


_EXPECTED_WIDTH = 9


def _read_rows(raw_csv):
    try:
        return [list(row) for row in csv.reader(
            io.StringIO(raw_csv, newline=""),
            delimiter=",",
            quotechar='"',
            doublequote=True,
            strict=False
        )]
    except csv.Error:
        return _manual_parse(raw_csv)


def _manual_parse(text):
    rows = []
    row = []
    field = []
    in_quotes = False
    quoted_field = False
    record_started = False
    i = 0
    length = len(text)

    while i < length:
        char = text[i]

        if in_quotes:
            if char == '"':
                if i + 1 < length and text[i + 1] == '"':
                    field.append('"')
                    i += 2
                    continue
                in_quotes = False
            else:
                field.append(char)
            record_started = True
            i += 1
            continue

        if char == '"' and not field and not quoted_field:
            in_quotes = True
            quoted_field = True
            record_started = True
            i += 1
            continue

        if char == ",":
            row.append("".join(field))
            field = []
            quoted_field = False
            record_started = True
            i += 1
            continue

        if char == "\r" or char == "\n":
            row.append("".join(field))
            rows.append(row)
            row = []
            field = []
            quoted_field = False
            record_started = False
            if char == "\r" and i + 1 < length and text[i + 1] == "\n":
                i += 2
            else:
                i += 1
            continue

        field.append(char)
        record_started = True
        i += 1

    if record_started or row or field or quoted_field:
        row.append("".join(field))
        rows.append(row)

    return rows


def _normalize_label(value):
    return re.sub(r"[^a-z0-9]+", "", value.strip().lower())


def _header_score(row):
    header_terms = {
        "date", "datetime", "day", "time", "timestamp",
        "qty", "quantity", "count", "amount",
        "id", "productid", "itemid", "sku", "code",
        "price", "cost", "value",
        "product", "productname", "producttype", "type", "name",
        "description", "productdescription", "details",
        "url", "uri", "link", "website",
        "comment", "comments", "note", "notes", "remark", "remarks"
    }
    normalized = [_normalize_label(value) for value in row]
    nonempty = [value for value in normalized if value]
    if len(nonempty) < 3:
        return -1

    matches = sum(1 for value in normalized if value in header_terms)
    alphabetic = sum(
        1 for value in row
        if re.search(r"[A-Za-z]", value) and not re.search(r"https?://", value, re.I)
    )
    numeric_like = sum(
        1 for value in row
        if re.fullmatch(r"\s*[-+$]?\d+(?:[./:-]\d+)*(?:\.\d+)?\s*", value or "")
    )

    if matches < 3:
        return -1
    return matches * 10 + alphabetic - numeric_like


def _fit_width(row, width):
    values = ["" if value is None else str(value) for value in row]
    if len(values) < width:
        return values + [""] * (width - len(values))
    if len(values) > width:
        return values[:width - 1] + [",".join(values[width - 1:])]
    return values


def parse_csv(raw_csv: str):
    if not isinstance(raw_csv, str):
        raw_csv = str(raw_csv)

    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    rows = _read_rows(raw_csv)

    best_index = None
    best_score = -1
    for index, row in enumerate(rows):
        score = _header_score(row)
        if score > best_score:
            best_score = score
            best_index = index

    if best_index is None or best_score < 0:
        columns = ["column_" + str(index + 1) for index in range(_EXPECTED_WIDTH)]
        data_rows = rows
    else:
        columns = _fit_width(rows[best_index], _EXPECTED_WIDTH)
        data_rows = rows[:best_index] + rows[best_index + 1:]

    return {
        "columns": columns,
        "rows": [_fit_width(row, _EXPECTED_WIDTH) for row in data_rows]
    }
